functions.private.snapshot_order_dispatch_rates():
CREATE OR REPLACE FUNCTION private.snapshot_order_dispatch_rates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
DECLARE v_rates record;
BEGIN
  IF NEW.assignment_id IS NOT NULL THEN
    SELECT COALESCE(assignment.commission_rate_snapshot, dispatch_group.commission_rate) AS commission_rate, COALESCE(assignment.dispatch_success_rate_snapshot, dispatch_group.dispatch_success_rate) AS success_rate INTO v_rates FROM public.dispatch_assignments AS assignment LEFT JOIN public.dispatch_group_orders AS dispatch_order ON dispatch_order.id = assignment.dispatch_order_id LEFT JOIN public.dispatch_order_pools AS pool ON pool.id = COALESCE(assignment.pool_id, dispatch_order.pool_id) JOIN public.dispatch_groups AS dispatch_group ON dispatch_group.id = COALESCE(assignment.group_id, pool.group_id, dispatch_order.group_id) WHERE assignment.assignment_id = NEW.assignment_id AND assignment.user_id = NEW.user_id AND assignment.status = 'accepted' AND assignment.order_submitted = false AND assignment.accepted_at + make_interval(mins => COALESCE(assignment.session_timeout_minutes_snapshot, dispatch_group.session_timeout_minutes, 10)) > now() FOR SHARE OF assignment, dispatch_group;
  ELSE
    PERFORM 1 FROM public.users WHERE id = NEW.user_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Order employee not found.'; END IF;
    IF EXISTS (SELECT 1 FROM public.dispatch_assignments WHERE user_id = NEW.user_id AND status IN ('pending', 'accepted')) THEN RAISE EXCEPTION 'Resolve active dispatch assignment before direct submission.'; END IF;
    SELECT dispatch_group.commission_rate, dispatch_group.dispatch_success_rate AS success_rate INTO v_rates FROM public.dispatch_group_members AS member JOIN public.dispatch_groups AS dispatch_group ON dispatch_group.id = member.group_id WHERE member.user_id = NEW.user_id AND dispatch_group.is_active AND dispatch_group.archived_at IS NULL FOR SHARE OF member, dispatch_group;
  END IF;
  IF v_rates.commission_rate IS NULL OR v_rates.success_rate IS NULL THEN RAISE EXCEPTION 'Order has no valid dispatch group rate.'; END IF;
  NEW.dispatch_commission_rate_snapshot := v_rates.commission_rate;
  NEW.dispatch_success_rate_snapshot := v_rates.success_rate;
  RETURN NEW;
END; $function$

functions.private.inherit_automation_message_deliv:
CREATE OR REPLACE FUNCTION private.inherit_automation_message_delivery_mode()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE v_delivery_mode text;
BEGIN
  IF NEW.automation_execution_id IS NULL THEN RETURN NEW; END IF;
  SELECT task.delivery_mode INTO v_delivery_mode
  FROM public.notification_automation_executions AS execution
  JOIN public.notification_automation_tasks AS task ON task.id = execution.task_id
  WHERE execution.id = NEW.automation_execution_id;
  IF v_delivery_mode IS NOT NULL AND NEW.delivery_mode IS DISTINCT FROM v_delivery_mode THEN
    UPDATE public.messages SET delivery_mode = v_delivery_mode WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$function$

functions.private.sync_notification_delivery_mode(:
CREATE OR REPLACE FUNCTION private.sync_notification_delivery_mode()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.delivery_mode IS NULL OR (NEW.delivery_mode = 'realtime_only' AND NEW.message_type = 'login_popup') THEN
      NEW.delivery_mode := CASE NEW.message_type WHEN 'login_popup' THEN 'login_only' ELSE 'realtime_only' END;
    ELSE
      NEW.message_type := CASE NEW.delivery_mode WHEN 'realtime_only' THEN 'realtime' ELSE 'login_popup' END;
    END IF;
  ELSIF NEW.delivery_mode IS DISTINCT FROM OLD.delivery_mode THEN
    NEW.message_type := CASE NEW.delivery_mode WHEN 'realtime_only' THEN 'realtime' ELSE 'login_popup' END;
  ELSIF NEW.message_type IS DISTINCT FROM OLD.message_type THEN
    NEW.delivery_mode := CASE NEW.message_type WHEN 'login_popup' THEN 'login_only' ELSE 'realtime_only' END;
  END IF;
  RETURN NEW;
END;
$function$

functions.public.set_customer_id():
CREATE OR REPLACE FUNCTION public.set_customer_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
IF NEW.customer_id IS NULL THEN
IF NEW.is_super = true THEN
NEW.customer_id := generate_super_customer_id();
ELSE
NEW.customer_id := generate_customer_id();
END IF;
END IF;
RETURN NEW;
END;
$function$

